function norm(v: unknown): string {
  return String(v || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase()
    .replace(/(\d),(\d)/g, '$1$2').replace(/[^A-Z0-9]+/g, ' ').replace(/\s+/g, ' ').trim()
}
function txt(...vs: unknown[]): string { for (const v of vs) { const s=String(v ?? '').trim(); if(s) return s } return '' }
function num(v: unknown): number {
  if (typeof v === 'number') return Number.isFinite(v) ? v : 0
  let s=String(v ?? '').replace(/R\$/gi,'').replace(/\s+/g,'')
  if(s.includes(',')&&s.includes('.')) s=s.replace(/\./g,'').replace(',','.')
  else if(s.includes(',')) s=s.replace(',','.')
  const n=Number(s.replace(/[^0-9.-]/g,'')); return Number.isFinite(n)?n:0
}
function descProduto(p:any){ return txt(p?.descricao,p?.nome,p?.nomeProduto,p?.produto) }
function nomeCliente(c:any){ return txt(c?.nomeRazaoSocial,c?.razaoSocial,c?.nomeFantasia,c?.nome,c?.clienteNome) }
function numeroVenda(v:any){ return txt(v?.numeroOrcamento,v?.numero,v?.codigo).replace(/\D/g,'') }
function temNfe(v:any){
  const fs=[v?.nfe,v?.numeroNfe,v?.numeroNotaFiscal,v?.chaveNfe,v?.chaveAcesso,v?.protocoloNfe,v?.danfe,v?.xmlNfe,v?.notaFiscal,v?.nf]
  return fs.some(x=>x!==null&&x!==undefined&&x!==''&&(typeof x!=='object'||Object.keys(x).length>0))
}
function protegido(v:any){
  const s=norm(txt(v?.status,v?.statusOrcamento,v?.situacao,v?.etapa,v?.tipo))
  if(['APROVADO','EFETIVADO','CONVERTIDO','PEDIDO','CONCLUIDO','FATURADO','EMITIDO','NFE','NOTA FISCAL'].some(x=>s.includes(norm(x)))) return true
  if(txt(v?.numeroPedido,v?.pedidoNumero,v?.pedidoId)||temNfe(v)) return true
  return v?.aprovado===true||v?.efetivado===true||v?.faturado===true
}
function localizarDescricao(produtos:any[], descricao:string){
  const alvo=norm(descricao)
  return produtos.filter(p=>norm(descProduto(p))===alvo)
}
function localizarCliente(clientes:any[], nome:string){
  const alvo=norm(nome)
  return clientes.filter(c=>norm(nomeCliente(c))===alvo)
}

export async function aplicarTodosOrcamentosDescricao(
  vendasEntrada:any[], produtosEntrada:any[], clientesEntrada:any[],
  atualizar: any,
  carregar: any
):Promise<any[]>{
  let vendas=Array.isArray(vendasEntrada)?vendasEntrada:[]
  const produtos=Array.isArray(produtosEntrada)?produtosEntrada:[]
  const clientes=Array.isArray(clientesEntrada)?clientesEntrada:[]
  for(const carga of ORCAMENTOS as any[]){
    // Os orçamentos 2462 e 2492 possuem revisões dedicadas e validadas.
    if (['2462', '2492'].includes(String(carga.numero))) continue
    const candidatos=vendas.filter(v=>numeroVenda(v)===String(carga.numero))
    if(candidatos.length>1){ console.warn(`[V295] ${carga.numero} ignorado: duplicidade pré-existente.`); continue }
    const existente=candidatos[0]
    if(existente&&protegido(existente)){ console.info(`[V295] ${carga.numero} preservado por estar aprovado/gerado.`); continue }

    const cs=localizarCliente(clientes,carga.cliente)
    if(cs.length!==1){ console.warn(`[V295] ${carga.numero} bloqueado: cliente retornou ${cs.length}.`); continue }
    const cliente=cs[0]

    const itens:any[]=[]
    let falha=''
    for(let i=0;i<carga.itens.length;i++){
      const origem=carga.itens[i]
      const ps=localizarDescricao(produtos,origem.descricao)
      if(ps.length!==1){ falha=`${origem.descricao}: ${ps.length} produto(s)`; break }
      const p=ps[0], custo=num(p?.custoMedioAtual??p?.custo??p?.ultimoCustoCompra)
      itens.push({
        id:`${carga.numero}-item-${i+1}`,produtoId:txt(p?.id),descricao:descProduto(p),
        unidade:txt(p?.unidade,p?.unidadeMedida,'Unidade'),quantidade:Number(origem.quantidade),
        valorUnitario:Number(origem.unitario),desconto:0,descontoValor:0,descontoPercentual:0,
        valorTotal:Number(Number(origem.total).toFixed(2)),custoUnitario:custo,
        custoTotal:Number((Number(origem.quantidade)*custo).toFixed(2)),
        estoqueDisponivel:num(p?.estoqueAtual??p?.estoque??p?.quantidadeEstoque),
        produtoVinculado:true,vinculoProdutoOrigem:'SOMENTE_DESCRICAO_EXATA_V295',
        ncm:txt(p?.ncm),cfop:txt(p?.cfopDentroEstado,p?.cfop),origem:txt(p?.origem),
        cest:txt(p?.cest),csosn:txt(p?.csosn),cstIcms:txt(p?.cstIcms),cstPis:txt(p?.cstPis),cstCofins:txt(p?.cstCofins)
      })
    }
    if(falha){ console.warn(`[V295] ${carga.numero} bloqueado sem alteração: ${falha}`); continue }

    const qtd=Number(itens.reduce((s,x)=>s+Number(x.quantidade||0),0).toFixed(2))
    const total=Number(itens.reduce((s,x)=>s+Number(x.valorTotal||0),0).toFixed(2))
    if(qtd!==Number(carga.quantidadeTotal)||total!==Number(carga.valorTotal)){
      console.warn(`[V295] ${carga.numero} bloqueado por validação de total.`); continue
    }

    const agora=new Date().toISOString()
    const id=txt(existente?.id)||(typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():`orcamento-${carga.numero}-${Date.now()}`)
    const registro={
      ...(existente||{}),id,tipo:'Orçamento',numero:String(carga.numero),numeroOrcamento:String(carga.numero),
      vendedor:txt(existente?.vendedor,'NATÁLIA VIEIRA'),
      clienteId:txt(cliente?.id,cliente?.clienteId,cliente?.codigo),clienteCodigo:txt(cliente?.codigo,cliente?.id),
      clienteNome:nomeCliente(cliente),clienteDocumento:txt(cliente?.cnpjCpf,cliente?.cnpj,cliente?.cpf,cliente?.documento).replace(/\D/g,''),
      clienteEmailNotaFiscal:txt(cliente?.emailNotaFiscal,cliente?.email),
      clienteInscricaoEstadual:txt(cliente?.inscricaoEstadual,cliente?.ie),
      cliente:{...(typeof existente?.cliente==='object'&&existente?.cliente?existente.cliente:{}),...cliente},
      dataEmissao:String(carga.emissao).split('/').reverse().join('-'),
      dataEntrega:String(carga.entrega).split('/').reverse().join('-'),
      dataValidade:String(carga.validade).split('/').reverse().join('-'),
      itens,itensEditadosManual:true,tipoDesconto:'valor',descontoInformado:0,descontoCalculado:0,
      desconto:0,descontoValor:0,frete:0,outrosCustos:0,subtotal:total,valorProdutos:total,
      totalFinal:total,total,valorTotal:total,quantidadeTotalItens:qtd,pagamentos:[],parcelas:[],
      formaPagamento:'',condicaoPagamento:'',condicoesPagamento:'',bancoCobranca:'',observacoesPagamento:'',
      status:'ABERTO',statusOrcamento:'Aberto',criadoEm:txt(existente?.criadoEm,agora),atualizadoEm:agora,
      marcadorInstalacao:MARCADOR,origemAtualizacao:MARCADOR
    }
    await atualizar('vendas',registro)
    const conf=await carregar('vendas')
    vendas=Array.isArray(conf?.data)?conf.data:vendas
  }
  return vendas
}
